function generateWeeksSelect(n){n.querySelector(".startWeekYear").addEventListener("change",function(){fillWeekSelect(this.value,n.querySelector(".startWeekWeek"))});n.querySelector(".endWeekYear").addEventListener("change",function(){fillWeekSelect(this.value,n.querySelector(".endWeekWeek"))});fillWeekSelect(n.querySelector(".startWeekYear").value,n.querySelector(".startWeekWeek"));fillWeekSelect(n.querySelector(".endWeekYear").value,n.querySelector(".endWeekWeek"))}function generateWeeksByYear(n){n=parseInt(n);let t=firstWeekOfYear(n),r=[],i=1;for(;;){let u=new Date(t);u.setDate(t.getDate()+6);let f=`${t.getFullYear()}/${t.getMonth()+1}/${t.getDate()}(${["日","一","二","三","四","五","六"][t.getDay()]})`,e=`${u.getFullYear()}/${u.getMonth()+1}/${u.getDate()}(${["日","一","二","三","四","五","六"][u.getDay()]})`;if(r.push({value:i,text:`第${i}週 ${f}~${e}`}),u.getFullYear()>n)break;t.setDate(t.getDate()+7);i++}return r}function fillWeekSelect(n,t){let i=generateWeeksByYear(n);t.options.length=0;i.forEach(n=>{let i=document.createElement("option");i.value=n.value;i.textContent=n.text;t.appendChild(i)})}